const years=[2025,2024,2023,2022,2021];let yf='all',pf='all',af='all';function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function medal(i){return '<span class="medal m'+(i+1)+'">'+(i+1)+'</span>'}function card(g){return '<article class="result-card"><div class="card-top"><span class="age">'+esc(g.age)+'</span><div class="medal-head"><span>1</span><span>2</span><span>3</span></div></div>'+[['Юноши',g.boys,''],['Девушки',g.girls,'girls']].map(([label,list,cl])=>'<div class="gender '+cl+'">'+label+'</div>'+list.map((p,i)=>'<div class="place-row">'+medal(i)+'<span class="name">'+esc(p[0])+'<span class="region">'+esc(p[1])+'</span></span></div>').join('')).join('<div style="height:13px"></div>')+'</article>'}function render(){const all=window.RESULTS;let ys=years.filter(y=>yf==='all'||String(y)===yf).filter(y=>Object.values(all[y]||{}).some(c=>Object.entries(c).some(([p,gs])=>(pf==='all'||p===pf)&&gs.some(g=>af==='all'||g.age===af))));document.getElementById('count').textContent=ys.length+' сезонов';document.getElementById('results').innerHTML=ys.map((y,i)=>{let cats=Object.keys(all[y]),body=cats.map(cat=>{let obj=all[y][cat],keys=Object.keys(obj).filter(p=>pf==='all'||p===pf),active=keys[0];if(!active)return '';return '<div class="category"><div class="programs">'+keys.map(p=>'<button class="program-tab '+(p===active?'active':'')+'" data-program="'+p+'">'+p+'</button>').join('')+'</div>'+keys.map(p=>'<div class="program-panel" data-panel="'+p+'" '+(p===active?'':'hidden')+'><div class="cards">'+obj[p].filter(g=>af==='all'||g.age===af).map(card).join('')+'</div></div>').join('')+'</div>'}).join(''),n=Object.values(all[y]).reduce((s,c)=>s+Object.values(c).reduce((a,g)=>a+g.filter(x=>af==='all'||x.age===af).length,0),0),label=cats.length>1?'младшие и старшие возраста':cats[0]==='junior'?'старшие возраста':'младшие возраста';return '<details class="year" '+(i===0?'open':'')+'><summary><span class="year-no">'+y+'</span><span class="year-info"><strong>Первенство России</strong><small>по русским шашкам · '+label+'</small></span><span class="year-count">'+n+' групп</span><span class="chevron">⌄</span></summary><div class="year-content">'+body+'<div class="note">Итоги по официальным публикациям Федерации шашек России.</div></div></details>'}).join('')||'<div class="empty">По выбранным фильтрам результатов нет.</div>';document.querySelectorAll('.program-tab').forEach(b=>b.onclick=()=>{let c=b.closest('.category');c.querySelectorAll('.program-tab').forEach(x=>x.classList.toggle('active',x===b));c.querySelectorAll('.program-panel').forEach(x=>x.hidden=x.dataset.panel!==b.dataset.program)})}document.querySelectorAll('.pill').forEach(b=>b.onclick=()=>{document.querySelectorAll('.pill').forEach(x=>x.classList.toggle('active',x===b));yf=b.dataset.year;render()});document.getElementById('programFilter').onchange=e=>{pf=e.target.value;render()};document.getElementById('ageFilter').onchange=e=>{af=e.target.value;render()};render();
